async function undo(verb,id){try{const response=await fetch(`/api/${verb}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});const result=await response.json();if(!response.ok)throw Error(result.error);await refresh({models:/^(approved)?model:/.test(id)});toast('Undone')}catch(error){toast(`Undo failed: ${error.message}`)}}
function toast(message,undoFn){const box=el('toast');box.replaceChildren(document.createTextNode(message));if(undoFn)box.append(document.createTextNode(' · '),button('Undo',undoFn));box.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.style.display='none',6500)}
el('base-toggle').onclick=cycleBase;applyBase();el('size-down').onclick=()=>stepSize(-1);el('size-up').onclick=()=>stepSize(1);applySize();document.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='b'&&!e.ctrlKey&&!e.altKey&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))cycleBase()});el('refresh').onclick=()=>refresh().catch(e=>toast(e.message));el('close').onclick=()=>close();el('prev-set').onclick=()=>go(-1);el('next-set').onclick=()=>go(1);document.querySelector('.shade').onclick=()=>close();window.onpopstate=()=>{if(!el('modal').hidden)close(true)};document.onkeydown=e=>{if(el('modal').hidden)return;if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;if(active==='concepts'&&!e.ctrlKey&&!e.altKey&&['Enter',' ','Escape'].includes(e.key)){e.preventDefault();if(e.repeat)return;if(e.key==='Enter')perform('approve',data[active][selected]);else if(e.key==='Escape')perform('reject',data[active][selected]);else skip()}else if(e.key==='Escape')close();if(e.key==='ArrowRight')go(1);if(e.key==='ArrowLeft')go(-1)};
refresh().catch(e=>toast(e.message));
